import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen2Test {



    @Test
    public void testPrintlnAfterPrint() throws IOException {
        // Arrange
        StringWriter out = new StringWriter();
        CSVFormat format = CSVFormat.DEFAULT;
        CSVPrinter printer = new CSVPrinter(out, format);
        String separator = format.getRecordSeparator();

        // Act
        printer.print("data");
        printer.println();

        // Assert
        // Expected: "data" + separator
        String expected = "data" + separator;
        Assert.assertEquals("The output should contain the printed value followed by the record separator", 
            expected, out.toString());

        printer.close();
    }




}

