package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for CSVPrinter#println()
 */
public class CSVPrinter_println_TriageGen2Test {







    @Test(expected = IOException.class)
    public void testPrintlnThrowsIOException() throws IOException {
        // Arrange
        // A custom Appendable that always throws IOException to test error propagation
        Appendable throwingAppendable = new Appendable() {
            @Override
            public Appendable append(CharSequence csq) throws IOException {
                throw new IOException("Simulated IO failure");
            }

            @Override
            public Appendable append(CharSequence csq, int start, int end) throws IOException {
                throw new IOException("Simulated IO failure");
            }

            @Override
            public Appendable append(char c) throws IOException {
                throw new IOException("Simulated IO failure");
            }
        };

        CSVPrinter printer = new CSVPrinter(throwingAppendable, CSVFormat.DEFAULT);

        // Act
        printer.println();

        // Assert handled by @Test(expected...)
    }
}
